/*
 * A040635  Continued fraction for sqrt(661).
 * https://oeis.org/A040635
 *
 * Offset:    0    (a(0) is the first term)
 * Keywords:  nonn, cofr, easy
 * Formula:   Continued fraction partial quotients of sqrt(661) a(0) =
 *            floor(sqrt(661)) = 25. For n > 0, the terms are generated by the
 *            standard recurrence: m_{k+1} = d_k * a_k - m_k d_{k+1} = (D -
 *            m_{k+1}^2) / d_k a_{k+1} = floor((a0 + m_{k+1}) / d_{k+1}) where
 *            D = 661, a0 = floor(sqrt(D)), m_0 = 0, d_0 = 1
 * Range:     u8 n <= 86, u16 n <= 86, u32 n <= 86, u64 n <= 86, u128 n <= 86,
 *            big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stdbool.h>
#include <stdlib.h>

/* Constant square‑root to be expanded. */
static const idx_t D = 661;

/* Cached sequence values. */
static seq_t *cache = NULL;
static size_t cache_cap = 0;   /* allocated capacity */
static size_t cache_used = 0;  /* next free index */

/* Current state of the continued‑fraction recurrence. */
static idx_t a0;          /* floor(sqrt(D)) */
static idx_t m;           /* m_k */
static idx_t d;           /* d_k */
static idx_t current_a;   /* a_k */

/* Ensure that the cache can hold at least ``needed`` elements. */
static void ensure_cap(size_t needed) {
    if (needed <= cache_cap)
        return;
    size_t new_cap = cache_cap ? cache_cap * 2 : 16;
    while (new_cap < needed)
        new_cap <<= 1;

    seq_t *tmp = (seq_t *)realloc(cache, new_cap * sizeof(seq_t));
    if (!tmp)
        exit(1);   /* Allocation failed – abort. */
    cache = tmp;
    cache_cap = new_cap;
}

/* Integer square‑root for the small constant D. */
static idx_t int_isqrt(idx_t x) {
    idx_t r = 0;
    while ((r + 1) * (r + 1) <= x)
        ++r;
    return r;
}

/* Public sequence function. */
seq_t a(idx_t n) {
    /* Lazy initialization of state and first term. */
    if (cache_used == 0) {
        a0 = int_isqrt(D);
        m  = 0;
        d  = 1;
        current_a = a0;

        ensure_cap(1);
        cache[0] = (seq_t)a0;
        cache_used = 1;
    }

    size_t target = (size_t)n;
    /* Generate terms up to index ``n`` if necessary. */
    while (cache_used <= target) {
        /* Compute the next recurrence values. */
        idx_t m_next = d * current_a - m;
        idx_t d_next = (D - m_next * m_next) / d;
        idx_t a_next = (a0 + m_next) / d_next;

        /* Store the new term. */
        ensure_cap(cache_used + 1);
        cache[cache_used] = (seq_t)a_next;
        ++cache_used;

        /* Advance state. */
        m = m_next;
        d = d_next;
        current_a = a_next;
    }

    return cache[target];
}
